CREATE TABLE profiles (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, goal TEXT NOT NULL, preferences TEXT NOT NULL, rowVersion INTEGER NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE profile_entries (id TEXT PRIMARY KEY, profileId TEXT NOT NULL REFERENCES profiles(id), kind TEXT NOT NULL, content TEXT NOT NULL, status TEXT NOT NULL, source TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), rowVersion INTEGER NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE companies (id TEXT PRIMARY KEY, name TEXT NOT NULL, nameKey TEXT NOT NULL UNIQUE, rowVersion INTEGER NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE offers (id TEXT PRIMARY KEY, companyId TEXT NOT NULL REFERENCES companies(id), title TEXT NOT NULL, direction TEXT NOT NULL, location TEXT NOT NULL, mode TEXT NOT NULL, contract TEXT NOT NULL, url TEXT NOT NULL, canonical TEXT UNIQUE, description TEXT NOT NULL, deadline TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), rowVersion INTEGER NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE applications (id TEXT PRIMARY KEY, offerId TEXT NOT NULL UNIQUE REFERENCES offers(id), status TEXT NOT NULL, sentAt TEXT NOT NULL, snapshot TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), rowVersion INTEGER NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE tasks (id TEXT PRIMARY KEY, title TEXT NOT NULL, due TEXT NOT NULL, applicationId TEXT REFERENCES applications(id), done INTEGER NOT NULL DEFAULT 0 CHECK(done IN (0,1)), archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), rowVersion INTEGER NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE events (id TEXT PRIMARY KEY, title TEXT NOT NULL, start TEXT NOT NULL, end TEXT NOT NULL, applicationId TEXT REFERENCES applications(id), place TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), rowVersion INTEGER NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE notes (id TEXT PRIMARY KEY, applicationId TEXT NOT NULL REFERENCES applications(id), text TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)), rowVersion INTEGER NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE materials (id TEXT PRIMARY KEY, title TEXT NOT NULL, kind TEXT NOT NULL, version TEXT NOT NULL, description TEXT NOT NULL, url TEXT NOT NULL, fileKey TEXT NOT NULL, fileName TEXT NOT NULL, sha256 TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>=0 AND (size<=20971520 OR (fileKey LIKE '%.bin' AND size<=104857600))), rowVersion INTEGER NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL, UNIQUE(title,version));
CREATE TABLE application_materials (applicationId TEXT NOT NULL REFERENCES applications(id), materialId TEXT NOT NULL REFERENCES materials(id), PRIMARY KEY(applicationId,materialId));
CREATE TABLE audit_events (id TEXT PRIMARY KEY, applicationId TEXT REFERENCES applications(id), at TEXT NOT NULL, action TEXT NOT NULL, text TEXT NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE INDEX tasks_due ON tasks(due,done,archived);
CREATE INDEX events_start ON events(start,archived);
CREATE INDEX audit_application ON audit_events(applicationId,at);
PRAGMA user_version=2;
